def match_handle(loc, tokens):
    """Process match blocks."""
    if not tokens:
        raise Exception("Invalid match block.")

    # Get the first token.
    token = tokens.pop(0)
    if token != "(":
        raise Exception("Invalid match block.")

    # Get the pattern.
    pattern = tokens.pop(0)
    if pattern == "(":
        pattern = match_handle(loc, tokens)

    # Get the optional pattern modifiers.
    modifiers = []
    while tokens and tokens[0] in ("?", "+", "*", "{", "}"):
        modifiers.append(tokens.pop(0))

    # Get the closing parenthesis.
    if tokens and tokens[0] == ")":
        tokens.pop(0)

    # Return the result.
    return (pattern, modifiers)

