def match_handle_pattern(loc, tokens):
    """Process match patterns."""
    if not tokens:
        raise Exception("Invalid match pattern.")

    # Get the first token.
    token = tokens.pop(0)
    if token == "(":
        pattern = match_handle(loc, tokens)
    else:
        pattern = token

    # Get the optional pattern modifiers.
    modifiers = []
    while tokens and tokens[0] in ("?", "+", "*", "{", "}"):
        modifiers.append(tokens.pop(0))

    # Return the result.
    return (pattern, modifiers)


def match_handle_patterns(loc, tokens):
    """Process match patterns."""
    patterns = []
    while tokens:
        if tokens[0] == ")":
            tokens.pop(0)
            break
        patterns.append(match_handle_pattern(loc, tokens))
    return patterns


